#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L;
    cin >> L;
    vector<long long> a(L);
    long long max_a = 0;
    for (int i = 0; i < L; i++) {
        cin >> a[i];
        max_a = max(max_a, a[i]);
    }

    const long long INF = 1e18;
    int limit = max_a; // b_i won't exceed this in optimal solution
    vector<long long> dp(limit + 2, INF);

    // first ear
    for (int v = 0; v <= limit; v++) {
        dp[v] = abs(a[0] - v);
    }

    for (int i = 1; i < L; i++) {
        vector<long long> ndp(limit + 2, INF);
        for (int v = 0; v <= limit; v++) {
            long long best_prev = dp[v];
            if (v > 0) best_prev = min(best_prev, dp[v-1]);
            if (v+1 <= limit) best_prev = min(best_prev, dp[v+1]);
            ndp[v] = best_prev + abs(a[i] - v);
        }
        dp = move(ndp);
    }

    long long ans = INF;
    for (int v = 0; v <= limit; v++) {
        ans = min(ans, dp[v]);
    }
    cout << ans << "\n";
    return 0;
}

