#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L;
    cin >> L;
    vector<long long> A(L + 1);
    for (int i = 1; i <= L; ++i) cin >> A[i];

    // Let x_i be the number of times Snuke passes point i-0.5.
    // A walk starting/ending at integers and turning only at integers
    // can realize exactly those nonnegative integer vectors x
    // such that x_i >= x_{i+1} and all x_i have the same parity.
    //
    // Ringo can increment/decrement one ear by one per operation,
    // so we want to minimize sum |A_i - x_i|.
    //
    // Since all x_i must have the same parity, try parity 0 and 1.
    // For fixed parity p, write x_i = p + 2*y_i with y_i >= 0.
    // Then x nonincreasing <=> y nonincreasing.
    // We need the closest nonincreasing sequence y to transformed targets.
    //
    // Cost for choosing y_i=t is |A_i - (p+2t)|.
    // This is equivalent to weighted L1 isotonic regression on
    // b_i = floor((A_i-p)/2) / ceil(...) form, but easiest here is to use
    // the standard "pool adjacent violators" idea on intervals because
    // the cost is convex in t.
    //
    // For integer t, define:
    //   cost_i(t) = |A_i - (p+2t)|
    // Its minimizer set is:
    //   if A_i%2==p : t = (A_i-p)/2
    //   else        : t = floor((A_i-p)/2) or ceil(...)
    // Thus each item contributes a convex piecewise-linear function with slope
    // changing around (A_i-p)/2. The minimizer of a block is any median of
    // the multiset consisting of two endpoints:
    //   l_i = floor((A_i-p)/2), r_i = ceil((A_i-p)/2),
    // clipped to t>=0.
    //
    // We can solve nonincreasing y by solving nondecreasing z on reversed order,
    // but simpler: maintain blocks and merge while block values increase.

    auto solve_parity = [&](int p) -> long long {
        struct Block {
            vector<long long> vals; // store l_i and r_i values for median
            int cnt;
        };

        vector<Block> st;

        auto block_value = [&](Block &b) -> long long {
            // median minimizing sum |t-v| over all v in vals, with t integer and t>=0
            auto &v = b.vals;
            nth_element(v.begin(), v.begin() + (v.size() - 1) / 2, v.end());
            long long med = v[(v.size() - 1) / 2];
            return max(0LL, med);
        };

        for (int i = 1; i <= L; ++i) {
            long long ai = A[i];
            long long l = floor((ai - p) / 2.0);
            long long r = (ai - p + 1) / 2;
            if (l < 0) l = 0;
            if (r < 0) r = 0;

            Block cur;
            cur.vals = {l, r};
            cur.cnt = 1;
            st.push_back(std::move(cur));

            while ((int)st.size() >= 2) {
                Block &b2 = st.back();
                Block &b1 = st[(int)st.size() - 2];

                long long v1 = block_value(b1);
                long long v2 = block_value(b2);

                // Need y nonincreasing, so block values must satisfy v1 >= v2.
                if (v1 >= v2) break;

                Block merged;
                merged.cnt = b1.cnt + b2.cnt;
                merged.vals.reserve(b1.vals.size() + b2.vals.size());
                for (auto x : b1.vals) merged.vals.push_back(x);
                for (auto x : b2.vals) merged.vals.push_back(x);

                st.pop_back();
                st.pop_back();
                st.push_back(std::move(merged));
            }
        }

        vector<long long> y;
        y.reserve(L);
        for (auto &b : st) {
            long long val = block_value(b);
            for (int k = 0; k < b.cnt; ++k) y.push_back(val);
        }

        long long ans = 0;
        for (int i = 0; i < L; ++i) {
            long long x = p + 2 * y[i];
            ans += llabs(A[i + 1] - x);
        }
        return ans;
    };

    cout << min(solve_parity(0), solve_parity(1)) << '\n';
    return 0;
}

