int main() {
    int L;
    scanf("%d", &L);
    long long *a = malloc((L+1) * sizeof(long long));
    long long sum_a = 0;
    for (int i = 1; i <= L; i++) {
        scanf("%lld", &a[i]);
        sum_a += a[i];
    }

    // Compute x[1] range
    long long low = 0, high = a[1];
    long long cur = 0; // x[1] coefficient: 1 for x[1], -1 for x[2], 1 for x[3], ...
    long long const_part = 0; // constant part of x[i] without t
    for (int i = 1; i <= L; i++) {
        // x[i] = const_part + cur * t
        // constraint: const_part + cur*t >= 0
        if (cur == 1) {
            // t >= -const_part
            long long need = -const_part;
            if (need > low) low = need;
        } else { // cur == -1
            // -t + const_part >= 0 => t <= const_part
            long long need = const_part;
            if (need < high) high = need;
        }
        // update for next
        const_part = a[i] - const_part;
        cur = -cur;
    }
    // also x[L+1] constraint:
    // const_part + cur*t >= 0
    if (cur == 1) {
        long long need = -const_part;
        if (need > low) low = need;
    } else {
        long long need = const_part;
        if (need < high) high = need;
    }

    long long t = low; // minimal t gives minimal sum x because sum x = L*const? Check sign:
    // sum x: each x[i] = const_part_i + cur_i * t
    // sum of cur_i over i=1..L+1: pattern +1 -1 +1 -1 ... => if L+1 odd => +1, else 0.
    // But we only need to compare at endpoints; since linear, min at low or high.
    long long t1 = low, t2 = high;
    long long sum_x1 = 0, sum_x2 = 0;
    long long cp = 0, c = 1;
    for (int i = 1; i <= L+1; i++) {
        long long xi1 = cp + c * t1;
        long long xi2 = cp + c * t2;
        sum_x1 += xi1;
        sum_x2 += xi2;
        if (i <= L) {
            cp = a[i] - cp;
            c = -c;
        }
    }
    long long sum_x = (sum_x1 < sum_x2) ? sum_x1 : sum_x2;
    printf("%lld\n", sum_x - sum_a);

    free(a);
    return 0;
}

