typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int L;
    if (scanf("%d", &L) != 1) return 0;

    ll *A = (ll*)malloc(sizeof(ll) * L);
    ll sum = 0;
    for (int i = 0; i < L; i++) {
        scanf("%lld", &A[i]);
        sum += A[i];
    }

    /* 
       Let x_i be the number of times Snuke passes i-0.5.
       Any walk that starts/ends at integers and turns only at integers
       yields a sequence x with:
         - x_i >= 0
         - x_i is even for all i except possibly on one contiguous segment,
           where x_i is odd.
       Equivalently, the parity pattern of x is any contiguous block of 1s.

       For fixed parity pattern, optimal x_i is:
         x_i = A_i     if parity matches A_i parity
         x_i = A_i +/- 1 minimizing |A_i - x_i|, so cost 1 otherwise
       Hence total cost equals the number of indices where chosen parity
       differs from parity(A_i).

       So we need a contiguous segment whose parity is odd, minimizing
       mismatches against b_i = A_i mod 2.
       If segment chosen, cost =
         (# zeros inside segment) + (# ones outside segment)
       = total_ones + (zeros-inside - ones-inside)
       = total_ones + len(segment) - 2*ones_inside

       Thus minimize cost by maximizing (2*ones_inside - len),
       i.e. maximum subarray sum on weights:
         +1 if A_i odd, -1 if A_i even.
       Also empty segment is allowed, giving cost = total_ones.
    */

    ll total_ones = 0;
    ll best = 0, cur = 0;

    for (int i = 0; i < L; i++) {
        ll w = (A[i] & 1LL) ? 1 : -1;
        if (A[i] & 1LL) total_ones++;
        cur += w;
        if (cur < 0) cur = 0;
        if (cur > best) best = cur;
    }

    ll ans = total_ones - best;
    printf("%lld\n", ans);

    free(A);
    return 0;
}

