public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int L = sc.nextInt();
        long[] a = new long[L];
        for (int i = 0; i < L; i++) a[i] = sc.nextLong();

        long[] cost = new long[2];
        for (int p = 0; p <= 1; p++) {
            long total = 0;
            for (int i = 0; i < L; i++) {
                long ai = a[i];
                // find closest non-negative integer with parity p
                long best;
                if (ai < 0) { best = p; }
                else {
                    if (ai % 2 == p) best = ai;
                    else best = ai - 1 >= 0 ? ai - 1 : ai + 1;
                    // but best must be >= 0
                    if (best < 0) best = p;
                }
                total += Math.abs(ai - best);
            }
            cost[p] = total;
        }
        System.out.println(Math.min(cost[0], cost[1]));
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int L = fs.nextInt();
        long ans = 0;
        for (int i = 0; i < L; i++) {
            long a = fs.nextLong();
            ans += a & 1L;
        }
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
